operations.reducer:
if (!action.input.projectId.trim()) {
    throw new MissingProjectIdentityError("A Speckle project id is required");
}

state.serverUrl = action.input.serverUrl;
state.projectId = action.input.projectId;
state.name = action.input.name || null;
state.description = action.input.description || null;
state.visibility = action.input.visibility || null;
state.syncedAt = action.input.syncedAt;

if (!action.input.speckleModelId.trim()) {
    throw new InvalidModelIdError("A Speckle model id is required");
}

const existing = state.models.find((m) => m.speckleModelId === action.input.speckleModelId);

if (existing) {
    existing.name = action.input.name;
    existing.displayName = action.input.displayName || null;
    existing.updatedAt = action.input.updatedAt || null;
    existing.latestVersionId = action.input.latestVersionId || null;
    existing.versionCount = action.input.versionCount;
    return;
}

state.models.push({
    id: action.input.id,
    speckleModelId: action.input.speckleModelId,
    name: action.input.name,
    displayName: action.input.displayName || null,
    updatedAt: action.input.updatedAt || null,
    latestVersionId: action.input.latestVersionId || null,
    versionCount: action.input.versionCount,
});

const index = state.models.findIndex((m) => m.speckleModelId === action.input.speckleModelId);

if (index === -1) {
    throw new ModelNotFoundError(`Model ${action.input.speckleModelId} is not mirrored here`);
}

state.models.splice(index, 1);
state.revisions = state.revisions.filter((r) => r.speckleModelId !== action.input.speckleModelId);
state.changes = state.changes.filter((c) => c.speckleModelId !== action.input.speckleModelId);

if (!action.input.versionId.trim() || !action.input.referencedObject.trim()) {
    throw new IncompleteRevisionError("Both versionId and referencedObject are required");
}

if (!state.models.some((m) => m.speckleModelId === action.input.speckleModelId)) {
    throw new UnknownRevisionModelError(`Model ${action.input.speckleModelId} must be mirrored before its revisions`);
}

const categories = action.input.categories.map((c) => ({
    id: c.id,
    speckleType: c.speckleType,
    objectCount: c.objectCount,
    unit: c.unit || null,
    volume: c.volume ?? null,
    area: c.area ?? null,
    length: c.length ?? null,
}));

const existing = state.revisions.find((r) => r.versionId === action.input.versionId);

if (existing) {
    existing.modelName = action.input.modelName || null;
    existing.referencedObject = action.input.referencedObject;
    existing.message = action.input.message || null;
    existing.sourceApplication = action.input.sourceApplication || null;
    existing.authorName = action.input.authorName || null;
    existing.createdAt = action.input.createdAt || null;
    existing.previewUrl = action.input.previewUrl || null;
    existing.objectCount = action.input.objectCount;
    existing.truncated = action.input.truncated ?? false;
    existing.categories = categories;
    existing.syncedAt = action.input.syncedAt;
} else {
    state.revisions.push({
        id: action.input.id,
        speckleModelId: action.input.speckleModelId,
        modelName: action.input.modelName || null,
        versionId: action.input.versionId,
        referencedObject: action.input.referencedObject,
        message: action.input.message || null,
        sourceApplication: action.input.sourceApplication || null,
        authorName: action.input.authorName || null,
        createdAt: action.input.createdAt || null,
        previewUrl: action.input.previewUrl || null,
        objectCount: action.input.objectCount,
        truncated: action.input.truncated ?? false,
        categories: categories,
        syncedAt: action.input.syncedAt,
    });
}

// Newest first, with a stable tie-break so the order never depends on arrival.
state.revisions.sort((a, b) => {
    const left = a.createdAt ?? "";
    const right = b.createdAt ?? "";

    if (left === right) return a.versionId.localeCompare(b.versionId);

    return right.localeCompare(left);
});

const index = state.revisions.findIndex((r) => r.versionId === action.input.versionId);

if (index === -1) {
    throw new RevisionNotFoundError(`Revision ${action.input.versionId} is not mirrored here`);
}

state.revisions.splice(index, 1);
state.changes = state.changes.filter(
    (c) => c.toVersionId !== action.input.versionId && c.fromVersionId !== action.input.versionId,
);

if (!action.input.toVersionId.trim()) {
    throw new IncompleteChangeError("A change needs the revision it leads to");
}

if (!state.revisions.some((r) => r.versionId === action.input.toVersionId)) {
    throw new ChangeRevisionUnknownError(`Revision ${action.input.toVersionId} is not mirrored here`);
}

const touched = (action.input.touchedElements || []).map((e) => ({
    id: e.id,
    identity: e.identity,
    objectId: e.objectId,
    speckleType: e.speckleType,
    kind: e.kind,
}));

// Counts are derived, never passed: they cannot then disagree with the list.
const countOf = (kind) => touched.filter((e) => e.kind === kind).length;

const deltas = (action.input.deltas || []).map((d) => ({
    id: d.id,
    speckleType: d.speckleType,
    unit: d.unit || null,
    countBefore: d.countBefore,
    countAfter: d.countAfter,
    volumeBefore: d.volumeBefore ?? null,
    volumeAfter: d.volumeAfter ?? null,
    areaBefore: d.areaBefore ?? null,
    areaAfter: d.areaAfter ?? null,
}));

const existing = state.changes.find(
    (c) => c.toVersionId === action.input.toVersionId && c.speckleModelId === action.input.speckleModelId,
);

if (existing) {
    existing.fromVersionId = action.input.fromVersionId || null;
    existing.detectedAt = action.input.detectedAt;
    existing.touchedElements = touched;
    existing.addedCount = countOf("ADDED");
    existing.removedCount = countOf("REMOVED");
    existing.modifiedCount = countOf("MODIFIED");
    existing.deltas = deltas;
    return;
}

state.changes.unshift({
    id: action.input.id,
    speckleModelId: action.input.speckleModelId,
    fromVersionId: action.input.fromVersionId || null,
    toVersionId: action.input.toVersionId,
    detectedAt: action.input.detectedAt,
    touchedElements: touched,
    addedCount: countOf("ADDED"),
    removedCount: countOf("REMOVED"),
    modifiedCount: countOf("MODIFIED"),
    deltas: deltas,
});
